import{_ as o,a0 as r,w as a,s as u,ao as s,I as e,x as i,a1 as p,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"精通Linux的“kill”命令 | LCTT x X-CMD","titleTemplate":false,"description":"精通Linux的“kill”命令 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通Linux的“kill”命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通Linux的“kill”命令 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Mastering the “Kill” Command in Linux","title":"精通Linux的“kill”命令","tag":"201310","desc":""},"relativePath":"201310/Mastering the “Kill” Command in Linux.md","filePath":"[post].md"}'),d={name:"201310/Mastering the “Kill” Command in Linux.md"};function m(k,l,x,f,L,T){const t=r("Link");return a(),u("div",null,[l[14]||(l[14]=s(`<h1 id="精通linux的-kill-命令" tabindex="-1">精通Linux的“kill”命令 <a class="header-anchor" href="#精通linux的-kill-命令" aria-label="Permalink to “精通Linux的“kill”命令”">​</a></h1><p>無論你使用哪種操作系統，你一定會遇到某個行為失常的應用，它把自己鎖死並拒絕關閉。在Linux(還有Mac)，你可以用一個&quot;kill&quot;命令強制終結它。在這個教程中，我們將展示給你多種方式使用&quot;kill&quot;命令終結應用。</p><p>###Kill命令和信號</p><p>當你執行一個&quot;kill&quot;命令，你實際上發送了一個信號給系統，讓它去終結不正常的應用。總共有60個你可以使用的信號，但是基本上你只需要知道SIGTERM(15)和SIGKILL(9)。</p><p>你可以用這個命令看到所有信號的列表：</p><pre><code>kill -l
</code></pre><p><img src="http://i1.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-list-signal.png" alt=""></p><ul><li>SIGTERM - 此信號請求一個進程停止運行。此信號是可以被忽略的。進程可以用一段時間來正常關閉，一個程序的正常關閉一般需要一段時間來保存進度並釋放資源。換句話説，它不是強制停止。</li><li>SIGKILL - 此信號強制進程立刻停止運行。程序不能忽略此信號，而未保存的進度將會丟失。</li></ul><p>使用&quot;kill&quot;的語法是：</p><pre><code>kill [信號或選項] PID(s)
</code></pre><p>默認信號（當沒有指定的時候）是SIGTERM。當它不起作用時，你可以使用下面的命令來強制kill掉一個進程:</p><pre><code>kill SIGKILL PID
</code></pre><p>或者</p><pre><code>kill -9 PID
</code></pre><p>這裏&quot;-9&quot;代表着SIGKILL信號。</p><p>如果你不知道應用的PID，僅需要運行這個命令：</p><pre><code>ps ux
</code></pre><p>它會顯示所有正在運行的應用還有應用的PID。</p><p><img src="http://i1.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-find-pid.png" alt=""></p><p>例如，要kill掉Chrome，我會運行命令：</p><pre><code>kill -9 3629
</code></pre><p>也可以在同一時間kill多個進程。</p><pre><code>kill -9 PID1 PID2 PID3
</code></pre><p>###PKill</p><p>&quot;pkill&quot;命令允許使用擴展的正則表達式和其它匹配方式。你現在可以使用應用的進程名kill掉它們，而不是使用PID。例如，要kill掉Firefox瀏覽器，只需要運行命令：</p><pre><code>pkill firefox
</code></pre><p>使用正則表達式匹配的話，你可以輸入進程名的部分字符，比如：</p><pre><code>pkill fire
</code></pre><p>為了避免kill掉錯誤的進程，你應該用一下&quot;pgrep -l [進程名]&quot;列表來匹配進程名稱。</p><p><img src="http://i0.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-pgrep-command.png" alt=""></p><p>###Killall</p><p>killall同樣使用進程名替代PID，並且它會kill掉所有的同名進程。例如，如果你正在運行多個Firefox瀏覽器的實例，可以用命令把它們全部kill掉:</p><pre><code>killall firefox
</code></pre><p>在Gnome中，你可以使用這個命令重啓Nautilus：</p><pre><code>killall nautilus
</code></pre><p>###xkill</p>`,36)),e("p",null,[l[1]||(l[1]=i('xkill 是圖形方式kill一個應用。當你在終端鍵入"xkill"，你的光標將立刻變成一個"十字"。你只需要做的是在不正常的應用上點擊一下，它就會立刻kill掉這個應用。如果你經常用的話，你也可以添加一個',-1)),p(t,{href:"http://www.maketecheasier.com/quick-tips/kill-unresponsive-application-in-ubuntu/"},{default:n(()=>[...l[0]||(l[0]=[i("鍵盤快捷鍵來激活xkill",-1)])]),_:1}),l[2]||(l[2]=i("。",-1))]),l[15]||(l[15]=e("p",null,"###結論",-1)),l[16]||(l[16]=e("p",null,'當應用不正常而導致系統掛起的時候，人們往往重啓計算機並且再一次開啓所有的任務。而有了這些"kill"命令，你將能夠更好的處理不正常的應用，從而避免導致系統崩潰。當你不想因一個不正常的進程而導致服務器宕機時，它尤其的有用。',-1)),l[17]||(l[17]=e("hr",null,null,-1)),e("p",null,[l[4]||(l[4]=i("via: ",-1)),p(t,{href:"http://www.maketecheasier.com/kill-command-in-linux/"},{default:n(()=>[...l[3]||(l[3]=[i("http://www.maketecheasier.com/kill-command-in-linux/",-1)])]),_:1})]),e("p",null,[l[7]||(l[7]=i("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[5]||(l[5]=[i("LCTT",-1)])]),_:1}),l[8]||(l[8]=i(" 原創翻譯，",-1)),p(t,{href:"http://linux.cn/"},{default:n(()=>[...l[6]||(l[6]=[i("Linux中國",-1)])]),_:1}),l[9]||(l[9]=i(" 榮譽推出",-1))]),e("p",null,[l[12]||(l[12]=i("譯者：",-1)),p(t,{href:"https://github.com/flsf"},{default:n(()=>[...l[10]||(l[10]=[i("flsf",-1)])]),_:1}),l[13]||(l[13]=i(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:n(()=>[...l[11]||(l[11]=[i("wxy",-1)])]),_:1})])])}const P=o(d,[["render",m]]);export{C as __pageData,P as default};
